package io.knowledgebrain.notification;
import java.net.*;import java.net.http.*;import java.time.Duration;import java.util.*;import tools.jackson.databind.json.JsonMapper;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;
final class GroupReviewAuthority {
 private final URI origin;private final HttpClient client;private final String key;private final JsonMapper json=JsonMapper.builder().enable(tools.jackson.databind.DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES).enable(tools.jackson.databind.DeserializationFeature.FAIL_ON_TRAILING_TOKENS).enable(tools.jackson.core.StreamReadFeature.STRICT_DUPLICATE_DETECTION).build();
 GroupReviewAuthority(String origin,String trust,String key)throws Exception{this.origin=NotificationHttp.origin(origin);client=NotificationHttp.client(trust);if(!key.matches("[A-Za-z0-9_-]{43}"))throw new IllegalArgumentException("Dedicated credential required");this.key=key;}
 GroupReviewStore.Access authorize(UUID group,String token,String trace){if(token==null||!token.matches("[A-Za-z0-9_-]{43}"))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED);try{var r=NotificationHttp.send(client,HttpRequest.newBuilder(origin.resolve("/internal/space/group-review-authorization")).header("Authorization","Bearer "+key).header("traceparent",trace).header("Content-Type","application/json").timeout(Duration.ofSeconds(5)).POST(HttpRequest.BodyPublishers.ofString(json.writeValueAsString(Map.of("token",token,"groupId",group)))).build(),2048);if(Set.of(401,403,404).contains(r.statusCode()))throw new ResponseStatusException(HttpStatus.valueOf(r.statusCode()));if(r.statusCode()!=200)throw new IllegalStateException();var a=json.readValue(r.body(),GroupReviewStore.Access.class);if(a==null||!a.groupId().equals(group)||a.membershipVersion()<1)throw new IllegalStateException();ReviewSignal.id(a.principalId().toString());ReviewSignal.id(a.spaceId().toString());return a;}catch(ResponseStatusException ex){throw ex;}catch(RuntimeException ex){throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE);}}
}
